DROP VIEW IF EXISTS replset.vw_expenses_adm_to_allocate CASCADE;  CREATE OR REPLACE VIEW replset.vw_expenses_adm_to_allocate AS  SELECT buhreg.date_period,     buhreg.account_name,     buhreg.account_code,     buhreg.organization_code,     buhreg.organization_name,     buhreg.shop_code,     buhreg.shop_name,     buhreg.cost_item_code,     buhreg.cost_item_name,     buhreg.amount,     buhreg.amountvat,     buhreg.amountwithvat    FROM vw_all_expenses_with_vat buhreg   WHERE ((buhreg.organization_code = '000000001'::text) AND (buhreg.cost_item_code <> '000000023'::text) AND (buhreg.shop_code = '000000001'::text))   GROUP BY buhreg.date_period, buhreg.account_name, buhreg.account_code, buhreg.organization_code, buhreg.organization_name, buhreg.shop_code, buhreg.shop_name, buhreg.cost_item_code, buhreg.cost_item_name, buhreg.amount, buhreg.amountvat, buhreg.amountwithvat UNION ALL  SELECT addreg.date_period,     chartofaccs._description AS account_name,     chartofaccs._code AS account_code,     orgs._code AS organization_code,     orgs._description AS organization_name,     shops._code AS shop_code,     shops._description AS shop_name,     costitems._code AS cost_item_code,     costitems._description AS cost_item_name,     sum(addreg.amount) AS amount,     sum(addreg.amountvat) AS amountvat,     (sum(addreg.amount) + sum(addreg.amountvat)) AS amountwithvat    FROM ((((additional_expenses addreg      JOIN dbo.buh__reference88 orgs ON (((addreg.organization_code = orgs._code) AND (orgs._code = '000000001'::text))))      JOIN dbo.buh__acc27 chartofaccs ON (((addreg.account_code = chartofaccs._code) AND (chartofaccs._code = '7210'::text))))      JOIN dbo.buh__reference117 costitems ON ((addreg.cost_item_code = costitems._code)))      JOIN dbo.buh__reference95 shops ON (((addreg.shop_code = shops._code) AND (shops._code = '000000001'::text))))   GROUP BY addreg.date_period, chartofaccs._description, chartofaccs._code, orgs._code, orgs._description, shops._code, shops._description, costitems._code, costitems._description   ORDER BY 1;
